// Задача человеку: вид → группа (команда EspoCRM). Команды заводит scripts/espocrm_bootstrap.py,
// сотрудников в них добавляет Заказчик в админке CRM.
const TEAM_BY_KIND = { handoff: 'Administratorzy' };
const kind = $('CRM operation').first().json.data.kind;
if (!TEAM_BY_KIND[kind]) {
  throw new Error(`Переходник CRM не знает вид Задачи человеку ${kind}`);
}
return [{ json: { team: TEAM_BY_KIND[kind] } }];

// Активные сотрудники группы по одному на элемент; пустая группа — один элемент без сотрудника:
// задача уйдёт группе без исполнителя.
const members = $input.first().json.list.map((user) => ({ json: { user_id: user.id } }));
return members.length ? members : [{ json: { user_id: null } }];

// Наименее загруженный: меньше всего открытых задач; при равенстве — первый по имени пользователя.
const members = $('Team members').all();
const loads = $input.all().map((item) => item.json.total);
const index = loads.indexOf(Math.min(...loads));
return [{ json: { assigned_user_id: members[index].json.user_id } }];

// Заявка в виде полей EspoCRM. Имя неизвестно — имя Беседы: без lastName CRM не пишет ни Клиента, ни Заявку.
// Телефон не в международном формате CRM отвергает (400): такой не пишем, Заявка важнее.
// В WhatsApp отправитель (wa_id) — номер Клиента без «+»: он телефон, если Клиент не назвал другой.
const d = $json.data;
const words = (d.name || '').trim().split(/\s+/).filter(Boolean);
const phone = (d.phone || (d.channel === 'whatsapp' ? `+${d.sender_id}` : '')).replace(/[\s().-]/g, '');
const vehicle = [d.vehicle_brand, d.vehicle_model].filter(Boolean).join(' ');
return {
  json: {
    person: {
      firstName: words.slice(0, -1).join(' ') || null,
      lastName: words.at(-1) || `${d.channel} · ${d.sender_id}`,
      ...(/^\+[0-9]{8,15}$/.test(phone) ? { phoneNumber: phone } : {}),
      // Согласие на рекламу меняет только ответ Клиента; не отвечал — в CRM как было.
      ...(typeof d.marketing_consent === 'boolean' ? { marketingConsent: d.marketing_consent } : {}),
    },
    vehicle: vehicle ? { name: vehicle, brand: d.vehicle_brand, model: d.vehicle_model } : null,
    lead: { channel: d.channel, service: d.service, description: d.description, desiredTime: d.desired_date },
  },
};

// Свободные слоты: по SLOT_MINUTES от начала каждого рабочего интервала календаря на сегодня и data.days
// дней вперёд, не раньше чем через LEAD_MINUTES от сейчас. Слот занят, если пересекается с Записью
// (отменённые, Not Held, CRM в поиск не отдаёт). Один слот — одна Запись: мест на одно время одно.
// Исключения календаря (WorkingTimeRange): Non-working — день закрыт, Working — свои часы.
const SLOT_MINUTES = 60;
const LEAD_MINUTES = 60;
// Пустой часовой пояс календаря в EspoCRM — часовой пояс CRM; у Заказчиков в Польше это Europe/Warsaw.
const DEFAULT_TIME_ZONE = 'Europe/Warsaw';
const ESPO_FORMAT = 'yyyy-MM-dd HH:mm:ss';

const days = $('CRM operation').first().json.data.days;
const calendar = $('Find working calendar').first().json.list[0];
const exceptions = $('Find working ranges').first().json.list;
const busy = $input.first().json.list.filter((m) => m.dateStart && m.dateEnd);
const zone = calendar.timeZone || DEFAULT_TIME_ZONE;
const now = DateTime.now().setZone(zone);
const earliest = now.plus({ minutes: LEAD_MINUTES });

function workingHours(day) {
  const date = day.toISODate();
  const exception = exceptions.find((range) => range.dateStart <= date && date <= range.dateEnd);
  if (exception) return exception.type === 'Working' ? exception.timeRanges || calendar.timeRanges : [];
  // Luxon: 1 — понедельник … 7 — воскресенье; EspoCRM: weekday0 — воскресенье.
  const weekday = day.weekday % 7;
  if (!calendar[`weekday${weekday}`]) return [];
  return calendar[`weekday${weekday}TimeRanges`] || calendar.timeRanges;
}

function at(day, time) {
  const [hour, minute] = time.split(':').map(Number);
  return day.set({ hour, minute, second: 0, millisecond: 0 });
}

function isBusy(startsAt, endsAt) {
  return busy.some((m) => m.dateStart < endsAt && m.dateEnd > startsAt);
}

function daySlots(day) {
  const slots = [];
  for (const [from, to] of workingHours(day)) {
    const end = at(day, to);
    for (let start = at(day, from); start.plus({ minutes: SLOT_MINUTES }) <= end; start = start.plus({ minutes: SLOT_MINUTES })) {
      const startsAt = start.toUTC().toFormat(ESPO_FORMAT);
      const endsAt = start.plus({ minutes: SLOT_MINUTES }).toUTC().toFormat(ESPO_FORMAT);
      if (start < earliest || isBusy(startsAt, endsAt)) continue;
      slots.push({ start: start.toFormat('yyyy-MM-dd HH:mm'), weekday: start.setLocale('en').toFormat('cccc'), starts_at: startsAt, ends_at: endsAt });
    }
  }
  return slots;
}

const slots = [];
for (let i = 0; i <= days; i++) slots.push(...daySlots(now.startOf('day').plus({ days: i })));
return { json: { calendar: true, time_zone: zone, slots } };

// Отчёт владельцу: сколько Заявок (Lead) и Записей (Meeting) создано в периоде [from, to) — всего
// и в каждом Канале. Один запрос — одно число (total при maxSize 1): читать сами записи не нужно.
// channel null — все записи периода, с Каналом и без (заведённые сотрудником без Канала).
const CHANNELS = ['messenger', 'instagram', 'whatsapp', 'call'];
const { from, to } = $('CRM operation').first().json.data;
return ['Lead', 'Meeting'].flatMap((entity) =>
  [null, ...CHANNELS].map((channel) => ({ json: { entity, channel, from, to } })),
);

// Ответы «Count records» идут в порядке запросов «Report queries».
const queries = $('Report queries').all().map((item) => item.json);
const totals = $input.all().map((item) => item.json.total);
const channels = {};
let total;
queries.forEach(({ entity, channel }, i) => {
  const key = entity === 'Lead' ? 'leads' : 'appointments';
  const counts = channel ? (channels[channel] ??= {}) : (total ??= {});
  counts[key] = totals[i];
});
return { json: { channels, total } };
